-- after-pairs.sql: READ ONLY on prod, one statement, AFTER 0446 (generated by scripts/build-sea-legs-migration.mjs: do not edit by hand).
-- Want head 20260818000446, own null, lanes null, asks 0, fn 1, pairs 64516, reaches_md5 8a49ba112085a5c0b57ef707bb23769e, haul_off 0 (world.haul_rows() is STABLE; about 4 s). STABLE functions only (public.npc_course_zones, public.harbour_zone).
begin transaction read only;
select jsonb_build_object(
  'head', (select max(version) from supabase_migrations.schema_migrations),
  'fn', (select count(*) from pg_proc p where p.oid = to_regprocedure('public.sea_leg_asks_keep()')),
  'pairs', (select count(*) from public.sea_leg_asks),
  'laws', (select to_jsonb(l) from (select
      (select string_agg(p.code, ' ' order by p.code) from public.ports p join public.sea_leg_asks s on s.from_port = p.id and s.to_port = p.id
        where p.kind = 'HARBOUR' and s.zones is distinct from array[public.harbour_zone(p.id)]) as own,
      (select string_agg(a.code || '-' || b.code, ' ' order by a.code, b.code)
         from public.npc_courses n join public.sea_leg_asks s on s.from_port = n.from_port and s.to_port = n.to_port
         join public.ports a on a.id = n.from_port join public.ports b on b.id = n.to_port
        where not s.zones @> public.npc_course_zones(n.course)) as lanes,
      (select count(*)::int from public.sea_leg_asks s join public.sea_leg_asks own on own.from_port = s.to_port and own.to_port = s.to_port
        where (s.wave_min, s.title_min) is distinct from
              ((select max(z.wave_min) from public.sea_zones z where z.code = any (s.zones || own.zones))::int,
               (select max(z.title_min) from public.sea_zones z where z.code = any (s.zones || own.zones))::int)) as asks) l),
  'reaches_md5', (select md5(string_agg(sr.code || sr.reaches::text, ',' order by sr.code collate "C")) from public.sea_reaches sr),
  'haul_off', (select count(*) from public.port_goods pg join world.haul_rows() h on h.port_id = pg.port_id and h.good_id = pg.good_id
                where (pg.haul_nm, pg.haul) is distinct from (h.haul_nm, h.haul)));
rollback;
